evaluation.reference:
Record Producto
  Define nombre As String;
  Define precio, stock As Integer;
EndRecord

Algorithm Productos
  Define productos As Vector<Producto> <- vector();
  Define nombre As String;
  Define precio, stock As Integer;
  For i <- 1 To 3 Do
    Read nombre;
    Read precio;
    Read stock;
    productos.append(Producto(nombre, precio, stock));
  EndFor
  For Each producto In productos Do
    Write producto.nombre, " ", producto.precio, " (quedan ", producto.stock, ")";
  EndFor
EndAlgorithm
